import type { Offer } from '@/types';
import raw from './catalogue.json';
import { settings } from './settings';

/**
 * POINTX catalogue, generated by scripts/build-catalogue.mjs. Items mirror
 * what the live app shows: X Store products, e-Coupons, Eat Around dining,
 * scan-&-pay Shops, Missions, Partner transfers, XTravel and Donations.
 */
export const catalogue: Offer[] = raw as Offer[];

const byId = new Map(catalogue.map((o) => [o.id, o]));

/** Look up an item by SKU. Throws in dev if a scripted SKU is missing. */
export function offer(id: string): Offer {
  const o = byId.get(id);
  if (!o) throw new Error(`Unknown SKU ${id}`);
  return o;
}

export const offers = (ids: string[]): Offer[] => ids.map(offer);
export const offersByBrand = (brandId: string): Offer[] => catalogue.filter((o) => o.brandId === brandId);
export const byType = (...types: Offer['offerType'][]): Offer[] => catalogue.filter((o) => types.includes(o.offerType));

