/* ------------------------------------------------------------------ */
/* Category chips — Shops tab and X Store tab (emoji icons as in app)   */
/* ------------------------------------------------------------------ */

export interface CategoryChip {
  id: string;
  label: string;
  emoji: string;
  /** Affinity key fed when tapped (category name). */
  affinity?: string;
  match: (o: Offer) => boolean;
}

export const shopChips: CategoryChip[] = [
  { id: 's-deal', label: 'Deal', emoji: '🏷️', match: (o) => o.offerType === 'Shop' && (!!o.pointsBackPct || (o.shopRate ?? 12.5) < 12.5) },
  { id: 's-all', label: 'All', emoji: '🏪', match: (o) => o.offerType === 'Shop' },
  { id: 's-fashion', label: 'Fashion', emoji: '👟', affinity: 'Fashion', match: (o) => o.offerType === 'Shop' && o.category === 'Fashion' },
  { id: 's-grocery', label: 'Grocery', emoji: '🛍️', affinity: 'Grocery', match: (o) => o.offerType === 'Shop' && o.category === 'Grocery' },
  { id: 's-jewelry', label: 'Jewelry & Watches', emoji: '💍', affinity: 'Jewelry & Watches', match: (o) => o.offerType === 'Shop' && o.category === 'Jewelry & Watches' },
  { id: 's-food', label: 'Food & Beverage', emoji: '🍜', affinity: 'Food & Beverage', match: (o) => o.offerType === 'Shop' && o.category === 'Food & Beverage' },
  { id: 's-health', label: 'Health & Beauty', emoji: '💄', affinity: 'Beauty', match: (o) => o.offerType === 'Shop' && o.category === 'Health & Beauty' },
  { id: 's-gas', label: 'Gas and Auto', emoji: '⛽', affinity: 'Gas & Auto', match: (o) => o.offerType === 'Shop' && o.category === 'Gas & Auto' },
  { id: 's-education', label: 'Education', emoji: '📚', affinity: 'Education', match: (o) => o.offerType === 'Shop' && o.category === 'Education' },
  { id: 's-entertainment', label: 'Entertainment', emoji: '🎬', affinity: 'Entertainment', match: (o) => o.offerType === 'Shop' && o.category === 'Entertainment' },
  { id: 's-travel', label: 'Travel', emoji: '🏝️', affinity: 'Travel', match: (o) => o.offerType === 'Shop' && o.category === 'Travel' },
  { id: 's-shopping', label: 'Shopping', emoji: '🛒', affinity: 'Shopping', match: (o) => o.offerType === 'Shop' && o.category === 'Shopping' },
];

export const storeChips: CategoryChip[] = [
  { id: 'x-deal', label: 'Deal', emoji: '🏷️', match: (o) => ['Product', 'eCoupon'].includes(o.offerType) && (o.discountPct ?? 0) >= 10 },
  { id: 'x-all', label: 'All', emoji: '🛒', match: (o) => ['Product', 'eCoupon', 'Dining', 'Donation'].includes(o.offerType) },
  { id: 'x-home', label: 'Home Appliances', emoji: '🧺', affinity: 'Home Appliances', match: (o) => o.category === 'Home Appliances' },
  { id: 'x-mobile', label: 'Mobile & Gadgets', emoji: '📱', affinity: 'Mobile & Gadgets', match: (o) => o.category === 'Mobile & Gadgets' },
  { id: 'x-kitchen', label: 'Kitchen', emoji: '🍳', affinity: 'Kitchen', match: (o) => o.category === 'Kitchen' },
  { id: 'x-beauty', label: 'Beauty', emoji: '💄', affinity: 'Beauty', match: (o) => o.category === 'Beauty' },
  { id: 'x-dining', label: 'Dining Vouchers', emoji: '🍽️', affinity: 'Dining', match: (o) => o.offerType === 'Dining' || (o.offerType === 'eCoupon' && o.category === 'Food & Beverage') },
  { id: 'x-ecoupon', label: 'e-Coupon', emoji: '🎟️', match: (o) => o.offerType === 'eCoupon' },
  { id: 'x-health', label: 'Health', emoji: '🧘', affinity: 'Health & Wellness', match: (o) => o.category === 'Health & Wellness' },
  { id: 'x-kids', label: 'Kid & Mom', emoji: '🧸', affinity: 'Kid & Mom', match: (o) => o.category === 'Kid & Mom' },
  { id: 'x-entertainment', label: 'Entertainment', emoji: '🎮', affinity: 'Entertainment', match: (o) => o.category === 'Entertainment' && o.offerType !== 'Shop' },
  { id: 'x-donations', label: 'Donations', emoji: '💝', match: (o) => o.offerType === 'Donation' },
  { id: 'x-travel', label: 'Travel', emoji: '🏝️', affinity: 'Travel', match: (o) => o.offerType === 'Travel' },
];

export const chipById = (id: string): CategoryChip | undefined => [...shopChips, ...storeChips].find((c) => c.id === id);

